TWComponent.script:
tw.local.sql = "select COMPONENT , DEFAULTCURRENCY, DEFAULTAMOUNT , CHARGEAMOUNT , ACCOUNTCLASS , ACCOUNTNO , BranchCode,  "
+"  currency , balance , balancesign , STANDARDEXRATE , NEGOTIATEDEXRATE , debitedamount from "+tw.env.LKP_DB_Schema+".ODC_CHARGESCOMMISSIONS    "
+"   where requesrid  = ? ";

tw.local.sqlParameters = new tw.object.listOf.SQLParameter();
tw.local.sqlParameters[0] =  new tw.object.SQLParameter();
tw.local.sqlParameters[0].value = tw.local.requestId;

//tw.local.odcRequest = {};
tw.local.odcRequest.ChargesAndCommissions = new tw.object.listOf.ChargesAndCommissions();


if(tw.local.sqlResults.listLength > 0)
{
	for(var i =0; i<tw.local.sqlResults[0].rows.listLength ; i++)
	{	

		tw.local.odcRequest.ChargesAndCommissions[i]  			              = new tw.object.ChargesAndCommissions();
		tw.local.odcRequest.ChargesAndCommissions[i].component   		        = tw.local.sqlResults[0].rows[i].data[0];
		tw.local.odcRequest.ChargesAndCommissions[i].defaultAmount                = tw.local.sqlResults[0].rows[i].data[1];
		tw.local.odcRequest.ChargesAndCommissions[i].defaultCurrency 	        = new tw.object.NameValuePair();
		tw.local.odcRequest.ChargesAndCommissions[i].defaultCurrency.value        = tw.local.sqlResults[0].rows[i].data[2];
		tw.local.odcRequest.ChargesAndCommissions[i].changeAmount                 = tw.local.sqlResults[0].rows[i].data[3];
		tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount               = new tw.object.AccountDetails();
		tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.accountClass  = new tw.object.NameValuePair();
		tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.accountClass.value   = tw.local.sqlResults[0].rows[i].data[4];
		/// need to check for charge and comm account type to know which field should be filled
		tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.customerAccountNo    = tw.local.sqlResults[0].rows[i].data[5];
		tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.glAccountNo          = tw.local.sqlResults[0].rows[i].data[5];
		
		tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.branchCode   = tw.local.sqlResults[0].rows[i].data[6];
		tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.currency     = new tw.object.NameValuePair();
		tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.currency.value    = tw.local.sqlResults[0].rows[i].data[7];
		tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.balance      = tw.local.sqlResults[0].rows[i].data[8];
		tw.local.odcRequest.ChargesAndCommissions[i].debitedAmount =new tw.object.AmountDetails();
		tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.balanceSign       = tw.local.sqlResults[0].rows[i].data[9];
		tw.local.odcRequest.ChargesAndCommissions[i].debitedAmount.standardExRate     = tw.local.sqlResults[0].rows[i].data[10];
		tw.local.odcRequest.ChargesAndCommissions[i].debitedAmount.negotiatedExRate   = tw.local.sqlResults[0].rows[i].data[11];
		tw.local.odcRequest.ChargesAndCommissions[i].debitedAmount.amountInAccount    = tw.local.sqlResults[0].rows[i].data[12];
		
	}

}

